export default {"sourceBranch":"content/vocabulary-original-batch-2026-11-14","status":"draft-unreviewed","fields":["senseId","headword","partOfSpeech","meaningJa","definitionEn","cefr","rawSynonyms","examples","imageHint","batch"],"sources":[{"batch":"original-20261114-b1-05","senses":67,"sha":"06f6b5fbf7d29f19b5dcd67d471b346d8a4c5aec"},{"batch":"original-20261114-b1-06","senses":28,"sha":"fd74884c261b3e8699cd74aa17de9cd77cf02a5f"},{"batch":"original-20261114-b1-07","senses":30,"sha":"3fc6f99e35de79267c5363ee453e0b13bcc65e61"},{"batch":"original-20261114-b1-08","senses":47,"sha":"7fda4269abe037459033ec3a42f3dd62926033d6"},{"batch":"original-20261114-b1-09","senses":32,"sha":"ea3ae3591e3d4a9c5a8e641399e39d0dbdd7e7d5"},{"batch":"original-20261114-b1-10","senses":43,"sha":"d92f3cfe7481fadcb484d099ae7f8243d78d6125"}],"rows":[["VDO-261114-H-00001","edge","noun","端・縁","the outer border of something","B1","border",[["The hikers stopped at the edge of the forest.","登山者たちは森の端で立ち止まりました。"],["She placed the glass away from the table's edge.","彼女はコップをテーブルの端から離して置きました。"]],"森の端の道","original-20261114-b1-05"],["VDO-261114-H-00002","edition","noun","版・刊行物","a particular version of a book or publication","B1","version",[["The library purchased the newest edition of the dictionary.","図書館はその辞書の最新版を購入しました。"],["This edition includes extra practice exercises.","この版には追加の練習問題が含まれています。"]],"新しい版の辞書","original-20261114-b1-05"],["VDO-261114-H-00003","educate","verb","教育する・学ばせる","to teach someone knowledge or skills","B1","teach",[["The program educates children about online safety.","そのプログラムは子どもたちにオンラインの安全を教えます。"],["Museums can educate visitors through interactive displays.","博物館は体験型展示を通して来館者に学びを提供できます。"]],"体験型の博物館","original-20261114-b1-05"],["VDO-261114-H-00004","effective","adjective","効果的な","producing the intended result","B1","successful",[["Short daily practice can be an effective learning method.","短時間の毎日の練習は効果的な学習方法になり得ます。"],["The new warning signs were effective in reducing accidents.","新しい警告標識は事故の減少に効果がありました。"]],"毎日の学習習慣","original-20261114-b1-05"],["VDO-261114-H-00005","elbow","noun","ひじ","the joint in the middle of the arm","B1","arm joint",[["He rested his elbow on the desk.","彼はひじを机にのせました。"],["The player hurt her elbow during practice.","その選手は練習中にひじを痛めました。"]],"ひじの関節","original-20261114-b1-05"],["VDO-261114-H-00006","election","noun","選挙","the process of choosing a leader by voting","B1","vote",[["Our class held an election for a new representative.","私たちのクラスは新しい代表を選ぶ選挙を行いました。"],["The election results were announced the next morning.","選挙結果は翌朝発表されました。"]],"クラス代表の投票","original-20261114-b1-05"],["VDO-261114-H-00007","electrical","adjective","電気の・電気を使う","connected with electricity or powered by it","B1","electric (related)",[["An electrical problem stopped the train.","電気系統の問題で列車が止まりました。"],["Students learned basic electrical safety in the workshop.","生徒たちは講習会で電気の基本的な安全対策を学びました。"]],"電気配線の点検","original-20261114-b1-05"],["VDO-261114-H-00008","electron","noun","電子","a tiny negatively charged particle in an atom","B1",null,[["An electron carries a negative electric charge.","電子は負の電荷を帯びています。"],["The teacher used a model to explain where electrons move.","先生は模型を使って電子の動きを説明しました。"]],"原子と電子の模型","original-20261114-b1-05"],["VDO-261114-H-00009","electronic","adjective","電子の・電子式の","using electronic parts or systems","B1","digital (often)",[["The library now uses electronic membership cards.","図書館は今では電子会員証を使っています。"],["She repaired a small electronic device.","彼女は小さな電子機器を修理しました。"]],"電子会員証の画面","original-20261114-b1-05"],["VDO-261114-H-00010","element","noun","要素・構成部分","a basic or important part of something","B1","component",[["Trust is an important element of teamwork.","信頼はチームワークの重要な要素です。"],["The design combines three simple elements.","そのデザインは3つの単純な要素を組み合わせています。"]],"図案の三つの要素","original-20261114-b1-05"],["VDO-261114-H-00011","element","noun","元素","a substance made of only one kind of atom","B1","chemical element",[["Oxygen is a chemical element.","酸素は化学元素です。"],["The students used a chart of the elements.","生徒たちは元素表を使いました。"]],"元素周期表","original-20261114-b1-05"],["VDO-261114-H-00012","embarrass","verb","恥ずかしい思いをさせる","to make someone feel ashamed or uncomfortable","B1","make self-conscious",[["The mistake embarrassed him during the presentation.","その間違いで彼は発表中に恥ずかしい思いをしました。"],["Please don't embarrass new students by asking personal questions.","個人的な質問をして新入生を困らせないでください。"]],"発表中に照れる生徒","original-20261114-b1-05"],["VDO-261114-H-00013","embarrassed","adjective","恥ずかしい・気まずい","feeling uncomfortable because others may notice a mistake","B1","self-conscious",[["She felt embarrassed when she forgot her lines.","彼女はせりふを忘れて恥ずかしく感じました。"],["I was embarrassed to ask for help at first.","私は最初助けを求めるのが恥ずかしかったです。"]],"質問をためらう生徒","original-20261114-b1-05"],["VDO-261114-H-00014","embarrassment","noun","恥ずかしさ・当惑","a feeling of discomfort about an awkward situation","B1","shame (related)",[["His face turned red with embarrassment.","恥ずかしさで彼の顔は赤くなりました。"],["She laughed to hide her embarrassment.","彼女は気まずさを隠すために笑いました。"]],"照れ笑いする人","original-20261114-b1-05"],["VDO-261114-H-00015","emerge","verb","現れる・姿を見せる","to come out or become visible","B1","appear",[["The sun emerged from behind the clouds.","太陽が雲の後ろから現れました。"],["A clear pattern emerged from the survey results.","調査結果から明確な傾向が浮かび上がりました。"]],"雲間から出る太陽","original-20261114-b1-05"],["VDO-261114-H-00016","emotional","adjective","感情的な・感動的な","connected with strong feelings","B1","moving (event)",[["The graduation speech was emotional for many students.","卒業式のスピーチは多くの生徒にとって感動的でした。"],["She found it difficult to discuss the emotional topic.","彼女は感情に関わる話題を議論するのが難しいと感じました。"]],"卒業式の感動","original-20261114-b1-05"],["VDO-261114-H-00017","emotionally","adverb","感情面で・精神的に","in a way that affects someone's feelings","B1","mentally (related)",[["The experience was emotionally challenging for the team.","その経験はチームにとって精神的につらいものでした。"],["Support from friends helped him emotionally.","友達の支えは彼を感情面で助けました。"]],"友達同士の支え","original-20261114-b1-05"],["VDO-261114-H-00018","emperor","noun","皇帝","the male ruler of an empire","B1","imperial ruler",[["The museum displays a portrait of an ancient emperor.","博物館は古代皇帝の肖像画を展示しています。"],["Students learned how the emperor governed the empire.","生徒たちは皇帝が帝国をどのように統治したか学びました。"]],"古代皇帝の肖像画","original-20261114-b1-05"],["VDO-261114-H-00019","emphasis","noun","強調・重点","special importance given to something","B1","focus",[["The lesson placed emphasis on speaking clearly.","授業は明確に話すことに重点を置きました。"],["She added emphasis by repeating the key phrase.","彼女は重要な表現を繰り返して強調しました。"]],"強調した学習ポイント","original-20261114-b1-05"],["VDO-261114-H-00020","empire","noun","帝国","a group of lands ruled by one powerful state","B1","imperial state",[["The map shows the empire at its greatest size.","その地図は帝国が最大だった時代を示しています。"],["Trade routes connected distant regions of the empire.","交易路は帝国の遠い地域同士をつないでいました。"]],"古代帝国の地図","original-20261114-b1-05"],["VDO-261114-H-00021","employment","noun","雇用・就業","the state of having paid work or giving people jobs","B1","work",[["The new factory created employment for local residents.","新しい工場は地元住民に雇用を生み出しました。"],["The report examined employment among young adults.","その報告書は若年成人の雇用状況を調べました。"]],"若者の雇用グラフ","original-20261114-b1-05"],["VDO-261114-H-00022","enable","verb","可能にする","to make it possible for someone to do something","B1","allow",[["Captions enable more students to follow the video.","字幕によってより多くの生徒が動画を理解できます。"],["The new ramp enables wheelchair access to the hall.","新しいスロープで車椅子でもホールに入れます。"]],"字幕付き授業動画","original-20261114-b1-05"],["VDO-261114-H-00023","enclose","verb","同封する・囲む","to put something inside an envelope or surround it","B1","include (letter)",[["Please enclose a copy of your application.","申請書のコピーを同封してください。"],["A stone wall encloses the small garden.","石の壁が小さな庭を囲んでいます。"]],"申請書の入った封筒","original-20261114-b1-05"],["VDO-261114-H-00024","encouragement","noun","励まし・勇気づけ","words or actions that make someone feel more confident","B1","support",[["The coach's encouragement helped her finish the race.","コーチの励ましのおかげで彼女はレースを完走できました。"],["A few words of encouragement changed his attitude.","わずかな励ましの言葉で彼の姿勢が変わりました。"]],"走者への励まし","original-20261114-b1-05"],["VDO-261114-H-00025","encouraging","adjective","励みになる・希望が持てる","giving someone hope or confidence","B1","promising",[["The early test results were encouraging.","初期の試験結果は希望の持てるものでした。"],["She received an encouraging message from her teacher.","彼女は先生から励みになるメッセージを受け取りました。"]],"励ましのメッセージ","original-20261114-b1-05"],["VDO-261114-H-00026","encyclopedia/encyclopaedia","noun","百科事典","a reference book or website giving information on many subjects","B1","reference work",[["We checked the encyclopedia for information about volcanoes.","私たちは火山について百科事典で調べました。"],["The online encyclopaedia included useful diagrams.","オンライン百科事典には役立つ図が含まれていました。"]],"火山の百科事典","original-20261114-b1-05"],["VDO-261114-H-00027","endanger","verb","危険にさらす","to put someone or something at risk","B1","threaten",[["Plastic waste can endanger sea animals.","プラスチックごみは海の動物を危険にさらすことがあります。"],["Driving too fast endangers people near the school.","スピードを出しすぎた運転は学校近くの人々を危険にさらします。"]],"海洋ごみと動物","original-20261114-b1-05"],["VDO-261114-H-00028","endless","adjective","終わりのない・果てしない","continuing without an apparent end","B1","never-ending",[["The road seemed endless in the summer heat.","夏の暑さの中、その道路は果てしなく続くように思えました。"],["The library offers endless opportunities to discover new ideas.","図書館には新しい考えに出会う無限の機会があります。"]],"どこまでも続く道","original-20261114-b1-05"],["VDO-261114-H-00029","endure","verb","耐える・持ちこたえる","to continue through pain or difficulty","B1","withstand",[["The hikers endured heavy rain on the mountain.","登山者たちは山での大雨に耐えました。"],["The old bridge endured many winter storms.","古い橋は何度も冬の嵐に耐えてきました。"]],"雨に耐える古い橋","original-20261114-b1-05"],["VDO-261114-H-00030","enemy","noun","敵・対立相手","a person or group opposed to another","B1","opponent (contextual)",[["The story's hero faced a powerful enemy.","物語の主人公は強力な敵に立ち向かいました。"],["The two former enemies agreed to cooperate.","かつて敵対していた2者は協力することで合意しました。"]],"物語の対立相手","original-20261114-b1-05"],["VDO-261114-H-00031","engaged","adjective","婚約している","having agreed to marry someone","B1","promised in marriage",[["My cousin got engaged last spring.","いとこは去年の春婚約しました。"],["The engaged couple planned a small wedding.","婚約中の2人は小さな結婚式を計画しました。"]],"婚約指輪","original-20261114-b1-05"],["VDO-261114-H-00032","engaged","adjective","熱心に取り組んでいる","actively involved in a task or activity","B1","involved",[["The students were fully engaged in the debate.","生徒たちは討論に熱心に参加していました。"],["She remained engaged throughout the workshop.","彼女は講習会の間ずっと積極的に取り組んでいました。"]],"熱心に討論する生徒","original-20261114-b1-05"],["VDO-261114-H-00033","engine","noun","エンジン・原動機","a machine that provides power for movement","B1","motor (related)",[["The mechanic checked the bus engine.","整備士はバスのエンジンを点検しました。"],["The boat's engine stopped near the harbor.","船のエンジンが港の近くで止まりました。"]],"バスのエンジン点検","original-20261114-b1-05"],["VDO-261114-H-00034","engineering","noun","工学・技術開発","the science of designing and building machines or structures","B1","applied science",[["She hopes to study engineering at university.","彼女は大学で工学を学びたいと考えています。"],["The project combines engineering with environmental science.","その計画は工学と環境科学を組み合わせています。"]],"橋の設計図","original-20261114-b1-05"],["VDO-261114-H-00035","Englishman","noun","イングランド出身の男性","a man from England","B1","man from England",[["An Englishman visited our class to talk about literature.","イングランド出身の男性が文学について話すためにクラスを訪れました。"],["The story follows an Englishman traveling through Asia.","その物語はアジアを旅するイングランド出身の男性を描いています。"]],"文学について話す来客","original-20261114-b1-05"],["VDO-261114-H-00036","enjoyable","adjective","楽しい・楽しめる","pleasant and giving satisfaction","B1","pleasant",[["The workshop was enjoyable for beginners.","その講習会は初心者にとって楽しいものでした。"],["We planned an enjoyable activity for the visitors.","私たちは訪問者のために楽しめる活動を計画しました。"]],"初心者の体験学習","original-20261114-b1-05"],["VDO-261114-H-00037","enjoyment","noun","楽しみ・喜び","the pleasure gained from doing something","B1","pleasure",[["Reading gives her great enjoyment.","読書は彼女に大きな楽しみを与えます。"],["The students' enjoyment was clear from their smiles.","生徒たちが楽しんでいることは笑顔から明らかでした。"]],"笑顔で読む生徒","original-20261114-b1-05"],["VDO-261114-H-00038","enrich","verb","豊かにする・充実させる","to improve something by adding value or variety","B1","enhance",[["Travel can enrich our understanding of other cultures.","旅行はほかの文化への理解を豊かにすることがあります。"],["The teacher enriched the lesson with real photographs.","先生は実際の写真で授業を充実させました。"]],"写真を使った授業","original-20261114-b1-05"],["VDO-261114-H-00039","entertainer","noun","芸能人・観客を楽しませる人","someone whose job is to perform for an audience","B1","performer",[["The entertainer performed a magic trick at the festival.","出演者は祭りで手品を披露しました。"],["A local entertainer visited the children's center.","地元の芸能人が児童センターを訪れました。"]],"手品のステージ","original-20261114-b1-05"],["VDO-261114-H-00040","enthusiasm","noun","熱意・情熱","strong excitement and interest in something","B1","passion",[["Her enthusiasm made the project more exciting.","彼女の熱意でその計画はよりわくわくするものになりました。"],["The students showed enthusiasm for the exchange session.","生徒たちは交流会に熱意を示しました。"]],"国際交流を楽しむ生徒","original-20261114-b1-05"],["VDO-261114-H-00041","enthusiast","noun","愛好家・熱心な人","a person very interested in a particular activity","B1","fan",[["A bird enthusiast helped us identify the species.","鳥の愛好家が私たちに種類の見分け方を教えてくれました。"],["The museum welcomed model train enthusiasts.","博物館は鉄道模型の愛好家たちを迎えました。"]],"鳥を観察する愛好家","original-20261114-b1-05"],["VDO-261114-H-00042","enthusiastic","adjective","熱心な・意欲的な","showing strong interest and enjoyment","B1","eager",[["The enthusiastic volunteers arrived early.","熱心なボランティアたちは早く到着しました。"],["She gave an enthusiastic introduction to the project.","彼女は計画について熱意のこもった紹介をしました。"]],"熱心なボランティア","original-20261114-b1-05"],["VDO-261114-H-00043","entire","adjective","全体の・全部の","including every part","B1","whole",[["The entire class joined the clean-up activity.","クラス全員が清掃活動に参加しました。"],["We spent the entire afternoon preparing the exhibition.","私たちは午後いっぱい展示の準備をしました。"]],"全員参加の清掃","original-20261114-b1-05"],["VDO-261114-H-00044","entirely","adverb","完全に・まったく","in every part or way","B1","completely",[["The story is entirely fictional.","その物語は完全な創作です。"],["The new system works entirely online.","新しいシステムはすべてオンラインで動きます。"]],"オンラインの仕組み","original-20261114-b1-05"],["VDO-261114-H-00045","entry","noun","参加・応募・提出作品","something submitted to a competition or list","B1","submission",[["Her entry won the photography contest.","彼女の応募作品は写真コンテストで優勝しました。"],["The competition received over a hundred entries.","その大会には100件を超える応募がありました。"]],"写真コンテストの作品","original-20261114-b1-05"],["VDO-261114-H-00046","entry","noun","入場・入口","permission or a way to enter a place","B1","admission",[["Entry to the garden is free for children.","その庭園は子どもの入場が無料です。"],["The museum has a separate entry for groups.","博物館には団体用の別入口があります。"]],"博物館の入口","original-20261114-b1-05"],["VDO-261114-H-00047","environmental","adjective","環境の・環境に関する","connected with nature and the effects of human activity","B1","ecological (related)",[["The students began an environmental project at school.","生徒たちは学校で環境プロジェクトを始めました。"],["The report describes the environmental impact of packaging.","その報告書は包装の環境への影響を説明しています。"]],"ごみ削減プロジェクト","original-20261114-b1-05"],["VDO-261114-H-00048","environmentalist","noun","環境保護活動家","someone who works to protect the natural environment","B1","conservationist",[["An environmentalist spoke about river pollution.","環境保護活動家が河川汚染について話しました。"],["The young environmentalist organized a community clean-up.","若い環境活動家は地域清掃を企画しました。"]],"川の清掃活動","original-20261114-b1-05"],["VDO-261114-H-00049","equal","adjective","等しい・平等な","the same in amount, size, or rights","B1","identical in amount",[["The two containers hold equal amounts of water.","2つの容器には同じ量の水が入ります。"],["Every student deserves an equal chance to participate.","すべての生徒に平等な参加機会があるべきです。"]],"同じ量の水の容器","original-20261114-b1-05"],["VDO-261114-H-00050","equally","adverb","等しく・同じ程度に","to the same degree or amount","B1","evenly (division)",[["Divide the work equally among the four members.","4人のメンバーで仕事を平等に分担してください。"],["Both solutions are equally useful.","2つの解決策は同じ程度に役立ちます。"]],"平等に分担する仕事","original-20261114-b1-05"],["VDO-261114-H-00051","equipment","noun","装置・器具・設備","tools or machines needed for a particular task","B1","gear",[["The club checked its equipment before the match.","部活動は試合前に用具を点検しました。"],["The lab received new equipment for measuring air quality.","研究室は空気の質を測るため新しい装置を受け取りました。"]],"空気質の測定器","original-20261114-b1-05"],["VDO-261114-H-00052","era","noun","時代","a period of history with particular features","B1","period",[["The museum shows clothing from the Meiji era.","博物館は明治時代の衣服を紹介しています。"],["Digital tools are changing education in the current era.","デジタル機器は現代の教育を変えています。"]],"時代別の衣服展示","original-20261114-b1-05"],["VDO-261114-H-00053","essence","noun","本質・核心","the most important quality or meaning of something","B1","core",[["Trust is the essence of a strong friendship.","信頼は強い友情の本質です。"],["She summarized the essence of the article in one sentence.","彼女は記事の要点を一文でまとめました。"]],"記事の核心を抜き出す","original-20261114-b1-05"],["VDO-261114-H-00054","establishment","noun","設立・創設","the act of starting an institution or system","B1","founding",[["The establishment of the new library took five years.","新しい図書館の設立には5年かかりました。"],["The town celebrated the establishment of its first school.","町は最初の学校の創設を祝いました。"]],"新しい図書館の開設","original-20261114-b1-05"],["VDO-261114-H-00055","eternal","adjective","永遠の・いつまでも続く","lasting forever or seeming to have no end","B1","everlasting",[["The poem speaks of eternal friendship.","その詩は永遠の友情について語っています。"],["The monument represents the hope for eternal peace.","その記念碑は永遠の平和への願いを表しています。"]],"平和を願う記念碑","original-20261114-b1-05"],["VDO-261114-H-00056","eternity","noun","永遠・無限の時間","time without an end","B1","forever",[["The journey felt like an eternity to the tired children.","疲れた子どもたちにはその旅が永遠に続くように感じられました。"],["The story explores what eternity might mean.","その物語は永遠が何を意味するのか探っています。"]],"果てしない道","original-20261114-b1-05"],["VDO-261114-H-00057","evenly","adverb","均等に・むらなく","in equal amounts or in a regular pattern","B1","uniformly",[["Spread the seeds evenly across the soil.","種を土全体にむらなくまいてください。"],["The teacher divided the cards evenly among the groups.","先生はグループ間でカードを均等に配りました。"]],"種を均等にまく","original-20261114-b1-05"],["VDO-261114-H-00058","eventually","adverb","最終的に・やがて","after some time or effort","B1","in the end",[["After several attempts, she eventually solved the puzzle.","何度か挑戦したあと彼女はついにパズルを解きました。"],["The small idea eventually became a school-wide project.","小さな考えがやがて全校規模の計画になりました。"]],"何度も挑戦するパズル","original-20261114-b1-05"],["VDO-261114-H-00059","evident","adjective","明白な・はっきりした","easy to see or understand","B1","obvious",[["The improvement was evident in the final results.","改善は最終結果にはっきり表れていました。"],["It became evident that the room was too small.","部屋が狭すぎることが明らかになりました。"]],"改善を示す成績グラフ","original-20261114-b1-05"],["VDO-261114-H-00060","exact","adjective","正確な・ぴったりの","completely correct or matching a particular amount","B1","precise",[["Please tell me the exact starting time.","正確な開始時刻を教えてください。"],["The scientist recorded the exact weight of the sample.","科学者は試料の正確な重さを記録しました。"]],"試料を量るはかり","original-20261114-b1-05"],["VDO-261114-H-00061","examination","noun","試験・検査","a formal test of knowledge or a careful check","B1","test",[["The entrance examination includes an English interview.","入学試験には英語面接が含まれています。"],["The doctor performed a careful examination of the patient.","医師は患者を丁寧に診察しました。"]],"英語面接の試験会場","original-20261114-b1-05"],["VDO-261114-H-00062","examiner","noun","試験官・検査をする人","a person who judges an examination","B1","assessor",[["The examiner asked me to explain my opinion.","試験官は私に意見を説明するよう求めました。"],["The driving examiner checked the applicant's skills.","運転試験官は受験者の技術を確認しました。"]],"面接試験官","original-20261114-b1-05"],["VDO-261114-H-00063","excellence","noun","優秀さ・卓越性","the quality of being extremely good","B1","high quality",[["The award recognizes excellence in student research.","その賞は生徒研究の優秀さを認めるものです。"],["The school encourages excellence through steady practice.","学校は地道な練習を通して卓越性を育みます。"]],"優れた研究への賞","original-20261114-b1-05"],["VDO-261114-H-00064","excess","noun","過剰・余分な量","more of something than is needed","B1","surplus",[["The school donated excess stationery to another class.","学校は余った文房具を別のクラスに寄付しました。"],["Excess sugar can change the taste of the sauce.","砂糖が多すぎるとソースの味が変わることがあります。"]],"余った文房具","original-20261114-b1-05"],["VDO-261114-H-00065","exchange rate","noun","為替レート","the value of one currency compared with another","B1","currency rate",[["Check the exchange rate before changing money.","両替する前に為替レートを確認してください。"],["A change in the exchange rate affected the trip budget.","為替レートの変動は旅行予算に影響しました。"]],"両替レートの表示","original-20261114-b1-05"],["VDO-261114-H-00066","excitedly","adverb","興奮して・わくわくしながら","in a way that shows great excitement","B1","enthusiastically",[["The students excitedly shared their new ideas.","生徒たちはわくわくしながら新しい考えを共有しました。"],["She waved excitedly when the visitors arrived.","訪問者が到着すると彼女は興奮して手を振りました。"]],"交流相手に手を振る","original-20261114-b1-05"],["VDO-261114-H-00067","excitement","noun","興奮・わくわくする気持ち","a strong feeling of happiness and interest","B1","thrill",[["The room was full of excitement before the performance.","発表前の部屋はわくわくした気持ちでいっぱいでした。"],["The news created excitement among the volunteers.","その知らせはボランティアたちを興奮させました。"]],"発表前の期待感","original-20261114-b1-05"],["VDO-261114-I-00001","exhausted","adjective","疲れ切った","extremely tired","B1","worn out",[["The runners were exhausted after the long race.","走者たちは長いレースのあと疲れ切っていました。"],["She felt exhausted after preparing the event all day.","一日中行事を準備して彼女はへとへとでした。"]],"レース後の疲れた走者","original-20261114-b1-06"],["VDO-261114-I-00002","existence","noun","存在・実在","the state of being real or alive","B1","being",[["The discovery confirmed the existence of the rare bird.","その発見は珍しい鳥の存在を確認しました。"],["Scientists are investigating the possible existence of water on the planet.","科学者たちはその惑星に水が存在する可能性を調べています。"]],"珍しい鳥の観察","original-20261114-b1-06"],["VDO-261114-I-00003","exit","noun","出口","a place where people can leave a building or area","B1","way out",[["The emergency exit is beside the stairs.","非常口は階段のそばにあります。"],["Follow the signs to the nearest exit.","最寄りの出口まで標識に従ってください。"]],"非常口の案内","original-20261114-b1-06"],["VDO-261114-I-00004","exit","verb","退出する・出る","to leave a building, vehicle, or place","B1","leave",[["Please exit the hall quietly after the ceremony.","式典後は静かにホールを出てください。"],["Passengers exited the train through the front door.","乗客たちは前方のドアから電車を降りました。"]],"電車から降りる乗客","original-20261114-b1-06"],["VDO-261114-I-00005","expense","noun","費用・出費","money spent on something","B1","cost",[["Travel was the biggest expense of the project.","交通費はその計画で最も大きな支出でした。"],["Keep a record of every expense during the trip.","旅行中のすべての出費を記録してください。"]],"旅行経費の一覧","original-20261114-b1-06"],["VDO-261114-I-00006","experienced","adjective","経験豊かな・熟練した","having gained skill through practice or work","B1","skilled",[["An experienced teacher guided the new staff.","経験豊かな教師が新任職員を指導しました。"],["The team asked an experienced climber for advice.","チームは経験豊かな登山者に助言を求めました。"]],"新人を指導する先生","original-20261114-b1-06"],["VDO-261114-I-00007","exploration","noun","探検・調査","the act of traveling or studying to discover new things","B1","investigation",[["The class began an exploration of local history.","クラスは地域の歴史の探究を始めました。"],["Space exploration has produced many new discoveries.","宇宙探査は多くの新しい発見をもたらしました。"]],"地域史を調べる生徒","original-20261114-b1-06"],["VDO-261114-I-00008","explosion","noun","爆発","a sudden violent release of energy","B1","blast",[["The science video explained the cause of the explosion.","理科の動画は爆発の原因を説明しました。"],["An explosion damaged the empty storage building.","爆発によって無人の倉庫が損傷しました。"]],"爆発の科学説明図","original-20261114-b1-06"],["VDO-261114-I-00009","expose","verb","さらす・露出させる","to leave someone or something without protection from a condition","B1","subject to",[["The broken roof exposed the room to rain.","壊れた屋根のため部屋は雨にさらされました。"],["Do not expose old paintings to direct sunlight.","古い絵画を直射日光にさらさないでください。"]],"雨にさらされた部屋","original-20261114-b1-06"],["VDO-261114-I-00010","expose","verb","明らかにする・暴く","to reveal something previously hidden","B1","reveal",[["The investigation exposed serious safety problems.","調査は重大な安全上の問題を明らかにしました。"],["The article exposed errors in the published figures.","その記事は公表された数値の誤りを明らかにしました。"]],"調査で判明した問題","original-20261114-b1-06"],["VDO-261114-I-00011","extensively","adverb","広範囲に・徹底的に","over a large area or in great detail","B1","widely",[["The researchers traveled extensively across the region.","研究者たちは地域全体を広範囲に移動しました。"],["The team tested the new software extensively.","チームは新しいソフトウェアを徹底的に試しました。"]],"ソフトの多項目検査","original-20261114-b1-06"],["VDO-261114-I-00012","extent","noun","程度・範囲","how large or serious something is","B1","degree",[["The survey revealed the extent of the problem.","調査は問題の深刻さを明らかにしました。"],["We measured the extent of the flood damage.","私たちは洪水被害の範囲を測りました。"]],"洪水範囲の地図","original-20261114-b1-06"],["VDO-261114-I-00013","extinct","adjective","絶滅した","no longer existing as a living species","B1","gone forever (species)",[["The dodo is an extinct bird.","ドードーは絶滅した鳥です。"],["Scientists study fossils of extinct animals.","科学者たちは絶滅した動物の化石を研究しています。"]],"ドードーの復元画","original-20261114-b1-06"],["VDO-261114-I-00014","extinction","noun","絶滅","the complete disappearance of a species","B1","disappearance of species",[["Habitat loss can lead to extinction.","生息地の消失は絶滅につながることがあります。"],["The museum explains the extinction of several ancient animals.","その博物館は複数の古代動物の絶滅を説明しています。"]],"絶滅した動物の展示","original-20261114-b1-06"],["VDO-261114-I-00015","extraordinary","adjective","並外れた・驚くべき","very unusual or remarkable","B1","exceptional",[["The young scientist made an extraordinary discovery.","若い科学者は驚くべき発見をしました。"],["Her extraordinary effort inspired the whole team.","彼女の並外れた努力はチーム全員を励ましました。"]],"驚くべき科学発見","original-20261114-b1-06"],["VDO-261114-I-00016","extreme","adjective","極端な・非常に激しい","much greater or stronger than usual","B1","severe",[["The region experienced extreme heat last summer.","その地域では去年の夏に極端な暑さがありました。"],["Extreme weather can disrupt transport services.","異常気象は交通機関に支障をきたすことがあります。"]],"猛暑を示す温度計","original-20261114-b1-06"],["VDO-261114-I-00017","extreme sports","noun","エクストリームスポーツ","sports involving unusual physical challenges and risks","B1","adventure sports",[["The documentary introduced several extreme sports.","そのドキュメンタリーはさまざまなエクストリームスポーツを紹介しました。"],["Safety training is essential for many extreme sports.","多くのエクストリームスポーツには安全訓練が不可欠です。"]],"ロッククライミング","original-20261114-b1-06"],["VDO-261114-I-00018","eyesight","noun","視力","the ability to see","B1","vision",[["Her eyesight improved with new glasses.","新しい眼鏡で彼女の視力が改善しました。"],["The school offers regular eyesight checks.","学校では定期的な視力検査を行っています。"]],"視力検査の表","original-20261114-b1-06"],["VDO-261114-I-00019","face to face","adverb","対面で・直接会って","in person and looking at each other","B1","in person",[["We finally met face to face after months of online calls.","何か月ものオンライン通話のあと私たちはついに対面で会いました。"],["The teachers discussed the plan face to face.","先生たちはその計画を直接会って話し合いました。"]],"海外の先生と対面交流","original-20261114-b1-06"],["VDO-261114-I-00020","face-to-face","adjective","対面の・直接会う","involving people meeting in the same place","B1","in-person",[["The workshop includes face-to-face activities.","その講習会には対面の活動が含まれています。"],["Face-to-face interviews helped students build confidence.","対面面接は生徒たちが自信を付ける助けになりました。"]],"対面の面接練習","original-20261114-b1-06"],["VDO-261114-I-00021","facility","noun","施設・設備","a building or place designed for a particular use","B1","center",[["The city opened a new sports facility.","市は新しいスポーツ施設を開設しました。"],["The school facility includes a science laboratory.","その学校施設には理科実験室が含まれています。"]],"スポーツ施設","original-20261114-b1-06"],["VDO-261114-I-00022","fade","verb","色あせる・薄れる","to become less bright, strong, or clear","B1","lose color",[["The poster faded after months in the sun.","ポスターは何か月も日光に当たり色あせました。"],["The sound of music faded as the train moved away.","電車が遠ざかるにつれ音楽の音は小さくなりました。"]],"色あせたポスター","original-20261114-b1-06"],["VDO-261114-I-00023","faint","adjective","かすかな・弱い","difficult to see, hear, or feel clearly","B1","weak",[["We heard a faint sound from the forest.","森からかすかな音が聞こえました。"],["There was a faint smell of flowers in the room.","部屋には花のかすかな香りがありました。"]],"遠くから聞こえる音","original-20261114-b1-06"],["VDO-261114-I-00024","faint","verb","気を失う・失神する","to briefly become unconscious","B1","pass out",[["The runner fainted in the heat and received medical help.","その走者は暑さで気を失い、医療支援を受けました。"],["She felt dizzy but did not faint.","彼女はめまいを感じましたが気は失いませんでした。"]],"暑さの中での救護","original-20261114-b1-06"],["VDO-261114-I-00025","faithful","adjective","忠実な・誠実な","remaining loyal or staying true to someone or something","B1","loyal",[["The dog remained faithful to its owner.","犬は飼い主に忠実でした。"],["The translation was faithful to the original meaning.","その翻訳は元の意味に忠実でした。"]],"忠実な翻訳の比較","original-20261114-b1-06"],["VDO-261114-I-00026","fake","adjective","偽の・本物でない","made to look real but not genuine","B1","false",[["The website used a fake photograph to attract attention.","そのウェブサイトは注目を集めるため偽の写真を使っていました。"],["We learned how to recognize fake news stories.","私たちは偽ニュースの見分け方を学びました。"]],"偽情報を検証する生徒","original-20261114-b1-06"],["VDO-261114-I-00027","fallen","adjective","倒れた・落ちた","having dropped to a lower position or fallen over","B1","downed",[["A fallen tree blocked the walking path.","倒木が遊歩道をふさいでいました。"],["Volunteers gathered fallen leaves from the garden.","ボランティアたちは庭の落ち葉を集めました。"]],"遊歩道の倒木","original-20261114-b1-06"],["VDO-261114-I-00028","fantasy","noun","空想・ファンタジー","a story or idea involving imaginary worlds or magic","B1","imaginary story",[["She wrote a fantasy story about a hidden city.","彼女は隠された都市についてのファンタジー物語を書きました。"],["The book mixes science fiction with fantasy.","その本はSFとファンタジーを組み合わせています。"]],"空想の都市の物語","original-20261114-b1-06"],["VDO-261114-J-00001","faraway","adjective","遠く離れた","located a long distance away","B1","distant",[["The children exchanged letters with a faraway school.","子どもたちは遠く離れた学校と手紙を交換しました。"],["A faraway island appeared on the horizon.","遠くの島が地平線に現れました。"]],"遠くの島","original-20261114-b1-07"],["VDO-261114-J-00002","farewell","noun","別れの挨拶・送別","an expression of goodbye when someone leaves","B1","goodbye",[["The class prepared a farewell card for the visitor.","クラスは訪問者に送別カードを用意しました。"],["Their farewell at the station was emotional.","駅での彼らの別れは感動的でした。"]],"駅での送別","original-20261114-b1-07"],["VDO-261114-J-00003","farming","noun","農業・農作業","the activity of growing crops or raising animals","B1","agriculture",[["Modern farming often uses sensors to save water.","現代の農業では節水のためにセンサーを使うことがよくあります。"],["Her family has worked in farming for generations.","彼女の家族は何世代にもわたって農業に携わっています。"]],"センサー農業","original-20261114-b1-07"],["VDO-261114-J-00004","farmland","noun","農地","land used for growing crops or keeping farm animals","B1","agricultural land",[["The town protected farmland from flooding.","その町は農地を洪水から守りました。"],["New houses were built beside the farmland.","農地の隣に新しい住宅が建ちました。"]],"農地と住宅","original-20261114-b1-07"],["VDO-261114-J-00005","farther","adverb","さらに遠くへ","to a greater physical distance","B1","further",[["We walked farther along the river than planned.","私たちは予定よりも川沿いを遠くまで歩きました。"],["The boat moved farther from the shore.","船は岸からさらに離れました。"]],"川沿いを歩く人","original-20261114-b1-07"],["VDO-261114-J-00006","farthest","adjective","最も遠い","located at the greatest physical distance","B1","most distant",[["The farthest village takes two hours to reach.","最も遠い村へ行くには2時間かかります。"],["She chose the farthest seat from the door.","彼女はドアから一番遠い席を選びました。"]],"地図上の最遠村","original-20261114-b1-07"],["VDO-261114-J-00007","fascinate","verb","魅了する・強く興味を引く","to attract someone's interest very strongly","B1","captivate",[["The astronaut's story fascinated the students.","宇宙飛行士の話は生徒たちを魅了しました。"],["The patterns on the butterfly's wings fascinated her.","チョウの羽の模様は彼女の強い興味を引きました。"]],"チョウの羽を観察","original-20261114-b1-07"],["VDO-261114-J-00008","fashionable","adjective","流行の・おしゃれな","popular and considered stylish at a particular time","B1","stylish",[["She bought a fashionable jacket at a secondhand shop.","彼女は古着屋でおしゃれな上着を買いました。"],["The district became known for its fashionable cafes.","その地区は流行のおしゃれなカフェで知られるようになりました。"]],"おしゃれな古着","original-20261114-b1-07"],["VDO-261114-J-00009","fasten","verb","しっかり留める・締める","to close or attach something securely","B1","secure",[["Fasten your seat belt before the bus starts.","バスが出発する前にシートベルトを締めてください。"],["He fastened the poster to the wall with tape.","彼はテープでポスターを壁にしっかり留めました。"]],"シートベルトを締める","original-20261114-b1-07"],["VDO-261114-J-00010","favorable/favourable","adjective","好都合な・好意的な","helpful or showing approval","B1","positive",[["The weather forecast was favorable for the event.","天気予報は行事に好都合な内容でした。"],["The proposal received favourable comments from parents.","その提案は保護者から好意的な意見を得ました。"]],"晴れの野外行事","original-20261114-b1-07"],["VDO-261114-J-00011","fax","noun","ファクス・FAX","a document sent electronically through a telephone system","B1","facsimile",[["The office received the signed form by fax.","事務室は署名済みの用紙をファクスで受け取りました。"],["The old machine could still print a fax.","古い機械はまだファクスを印刷できました。"]],"昔のファクス機","original-20261114-b1-07"],["VDO-261114-J-00012","feast","noun","ごちそう・盛大な食事","a large special meal shared with others","B1","banquet",[["The host family prepared a feast for the visitors.","受け入れ家庭は訪問者のためにごちそうを用意しました。"],["We enjoyed a harvest feast after working in the field.","私たちは畑で働いたあと収穫祝いの食事を楽しみました。"]],"収穫祭の料理","original-20261114-b1-07"],["VDO-261114-J-00013","fellow","adjective","同じ仲間の・同僚の","belonging to the same group or sharing a situation","B1","other (same group)",[["She shared the results with her fellow researchers.","彼女は同じ研究者仲間と結果を共有しました。"],["The captain encouraged his fellow players.","キャプテンはチームの仲間を励ましました。"]],"チームの仲間","original-20261114-b1-07"],["VDO-261114-J-00014","ferry","noun","フェリー・渡し船","a boat that carries people or vehicles across water","B1","passenger boat",[["The ferry leaves the island every morning.","フェリーは毎朝その島を出発します。"],["We took our bicycles onto the ferry.","私たちは自転車をフェリーに載せました。"]],"自転車を載せたフェリー","original-20261114-b1-07"],["VDO-261114-J-00015","festive","adjective","お祝いの・華やかな","connected with a festival or celebration","B1","celebratory",[["The street looked festive with colorful lanterns.","通りは色とりどりの提灯で華やかに見えました。"],["Students created festive decorations for the hall.","生徒たちはホール用のお祝いの飾りを作りました。"]],"祭りの提灯","original-20261114-b1-07"],["VDO-261114-J-00016","fetch","verb","取ってくる・連れてくる","to go somewhere and bring someone or something back","B1","retrieve",[["Please fetch a clean towel from the cupboard.","戸棚から清潔なタオルを取ってきてください。"],["The dog fetched the ball from the grass.","犬は芝生からボールを取ってきました。"]],"ボールを持ち帰る犬","original-20261114-b1-07"],["VDO-261114-J-00017","feverishly","adverb","必死に・熱心に","with intense and often hurried effort","B1","frantically",[["The team worked feverishly before the deadline.","チームは締め切り前に必死に作業しました。"],["Researchers searched feverishly for the missing records.","研究者たちは行方不明の記録を必死に探しました。"]],"締切前に作業する人","original-20261114-b1-07"],["VDO-261114-J-00018","fifth","adjective","5番目の","coming after four others in order","B1","number five in order",[["The fifth question was the most difficult.","5番目の問題が最も難しかったです。"],["She lives on the fifth floor of the building.","彼女はその建物の5階に住んでいます。"]],"5番目の番号札","original-20261114-b1-07"],["VDO-261114-J-00019","filling","noun","詰め物・中身","a substance put inside food or an object","B1","stuffing",[["The sandwich has a filling of egg and vegetables.","そのサンドイッチには卵と野菜の具が入っています。"],["She chose a sweet bean filling for the pastry.","彼女はその菓子にあんこの具を選びました。"]],"サンドイッチの具","original-20261114-b1-07"],["VDO-261114-J-00020","filling","adjective","腹持ちのよい","making you feel that you have eaten enough","B1","satisfying",[["The vegetable soup was surprisingly filling.","その野菜スープは意外とお腹にたまりました。"],["Rice and beans make a filling lunch.","ご飯と豆は腹持ちのよい昼食になります。"]],"豆とご飯の昼食","original-20261114-b1-07"],["VDO-261114-J-00021","film-maker","noun","映画製作者・映像作家","a person who makes films or videos","B1","director (sometimes)",[["The young film-maker documented life on the island.","若い映像作家は島の暮らしを記録しました。"],["A film-maker taught students how to edit interviews.","映像作家が生徒にインタビュー動画の編集方法を教えました。"]],"インタビューを撮る人","original-20261114-b1-07"],["VDO-261114-J-00022","filter","noun","フィルター・ろ過器","a device that removes unwanted material from air or liquid","B1","strainer (contextual)",[["The water filter removed dirt from the rainwater.","浄水フィルターは雨水から汚れを取り除きました。"],["The air filter needs to be replaced regularly.","空気フィルターは定期的に交換する必要があります。"]],"水のろ過フィルター","original-20261114-b1-07"],["VDO-261114-J-00023","filter","verb","ろ過する・選別する","to remove unwanted material or select items by a condition","B1","screen",[["The machine filters dust from the air.","その機械は空気中のほこりを除去します。"],["Students filtered the survey data by age.","生徒たちは調査データを年齢別に絞り込みました。"]],"アンケートを条件で絞る","original-20261114-b1-07"],["VDO-261114-J-00024","finance","noun","財政・資金管理","the management of money for a person or organization","B1","money management",[["The workshop introduced basic personal finance.","その講座は基本的な家計管理を紹介しました。"],["The club discussed how to finance its activities.","その部活動は活動資金をどう賄うか話し合いました。"]],"家計管理の帳簿","original-20261114-b1-07"],["VDO-261114-J-00025","finance","verb","資金を提供する","to provide money needed for a project","B1","fund",[["Local businesses helped finance the festival.","地元企業は祭りの資金提供を手伝いました。"],["The city financed the new community center.","市は新しい地域交流センターの建設費を負担しました。"]],"地域交流センターの建設","original-20261114-b1-07"],["VDO-261114-J-00026","finding","noun","研究・調査で得た結果","information discovered by a study or investigation","B1","result",[["The finding surprised the research team.","その発見は研究チームを驚かせました。"],["The report's main findings were shown in a chart.","報告書の主な調査結果はグラフに示されました。"]],"調査結果のグラフ","original-20261114-b1-07"],["VDO-261114-J-00027","finger","noun","指","one of the long parts at the end of a hand","B1","digit",[["She pointed at the map with her finger.","彼女は指で地図を指しました。"],["He injured a finger while playing basketball.","彼はバスケットボール中に指をけがしました。"]],"地図を指さす手","original-20261114-b1-07"],["VDO-261114-J-00028","fire station","noun","消防署","a building where firefighters and their vehicles are based","B1","firehouse",[["Our class visited the fire station for a safety lesson.","私たちのクラスは安全学習のため消防署を訪れました。"],["The new fire station is near the river.","新しい消防署は川の近くにあります。"]],"消防署と消防車","original-20261114-b1-07"],["VDO-261114-J-00029","firefighter","noun","消防士","a person trained to put out fires and rescue people","B1","fire service worker",[["The firefighter showed us how to use an extinguisher.","消防士は消火器の使い方を見せてくれました。"],["Firefighters rescued a dog from the flooded house.","消防士たちは浸水した家から犬を救助しました。"]],"消火器を教える消防士","original-20261114-b1-07"],["VDO-261114-J-00030","firework","noun","花火","an object that produces bright lights in the sky when lit","B1","pyrotechnic display (related)",[["A firework lit up the sky above the harbor.","花火が港の上空を照らしました。"],["The festival ended with colorful fireworks.","祭りは色鮮やかな花火で締めくくられました。"]],"港の花火","original-20261114-b1-07"],["VDO-261114-K-00001","firm","adjective","しっかりした・固い","solid and not easily moved or changed","B1","solid",[["The wooden chair felt firm and stable.","その木の椅子はしっかりしていて安定していました。"],["The coach gave a firm answer about the rules.","コーチは規則について断固とした返答をしました。"]],"安定した木の椅子","original-20261114-b1-08"],["VDO-261114-K-00002","firm","noun","会社・企業","a business organization providing goods or services","B1","company",[["She works for a small design firm.","彼女は小さなデザイン会社で働いています。"],["The firm hired three new engineers.","その会社は新しい技術者を3人雇いました。"]],"小さなデザイン会社","original-20261114-b1-08"],["VDO-261114-K-00003","firmly","adverb","しっかりと・断固として","in a strong and steady manner","B1","securely",[["Hold the handle firmly while climbing.","登る間は取っ手をしっかり握ってください。"],["She firmly refused to share her password.","彼女はパスワードを教えることをきっぱり断りました。"]],"取っ手を握る手","original-20261114-b1-08"],["VDO-261114-K-00004","first floor","noun","1階（米）・2階（英）","the level of a building called the first floor in a particular country","B1","first level (US)",[["In American English, the first floor is usually at street level.","アメリカ英語では通常、first floorは地上階を指します。"],["The British hotel put our room on the first floor, above reception.","イギリスのホテルでは私たちの部屋は受付の上の階にありました。"]],"米英で異なる階数","original-20261114-b1-08"],["VDO-261114-K-00005","first lady","noun","大統領などの配偶者に対する称号","the title commonly used for the wife of a president or similar leader","B1","president's spouse (contextual)",[["The first lady attended the school charity event.","ファーストレディーは学校の慈善行事に出席しました。"],["The museum displayed letters written by a former first lady.","博物館はかつてのファーストレディーが書いた手紙を展示しました。"]],"公的行事の来賓","original-20261114-b1-08"],["VDO-261114-K-00006","first-floor","adjective","1階の（米）・2階の（英）","located on the level called the first floor","B1","at first-floor level",[["The American school has a first-floor library near the entrance.","そのアメリカの学校には入口近くの1階に図書館があります。"],["Our British host showed us a first-floor bedroom upstairs.","イギリスのホストは階段を上がった先の2階の寝室を見せてくれました。"]],"建物の階層図","original-20261114-b1-08"],["VDO-261114-K-00007","fitness","noun","体力・健康な状態","the condition of being physically healthy and strong","B1","physical condition",[["Cycling improved her fitness over the summer.","自転車に乗ることで夏の間に彼女の体力は向上しました。"],["The club tracks fitness through regular exercises.","その部活動は定期的な運動を通して体力を確認します。"]],"体力測定の生徒","original-20261114-b1-08"],["VDO-261114-K-00008","flash","noun","一瞬の強い光","a short sudden burst of bright light","B1","burst of light",[["A flash of lightning lit the sky.","稲妻の閃光が空を照らしました。"],["The camera flash surprised the cat.","カメラのフラッシュに猫は驚きました。"]],"稲妻の閃光","original-20261114-b1-08"],["VDO-261114-K-00009","flash","verb","一瞬光る・点滅する","to shine suddenly or repeatedly for a short time","B1","blink",[["A warning light flashed on the dashboard.","警告灯がダッシュボードで点滅しました。"],["The lighthouse flashed across the dark sea.","灯台の光が暗い海に向かって点滅しました。"]],"点滅する警告灯","original-20261114-b1-08"],["VDO-261114-K-00010","flavor/flavour","noun","風味・味わい","the particular taste of a food or drink","B1","taste",[["The soup has a rich mushroom flavor.","そのスープには豊かなキノコの風味があります。"],["She liked the fresh lemon flavour of the cake.","彼女はケーキのさわやかなレモンの風味が気に入りました。"]],"レモン風味のケーキ","original-20261114-b1-08"],["VDO-261114-K-00011","flock","noun","鳥の群れ・羊の群れ","a group of birds or sheep together","B1","group",[["A flock of birds flew above the rice fields.","鳥の群れが田んぼの上を飛びました。"],["The farmer moved the flock of sheep to new grass.","農家は羊の群れを新しい牧草地へ移しました。"]],"田んぼの上の鳥の群れ","original-20261114-b1-08"],["VDO-261114-K-00012","flow","verb","流れる","to move smoothly and continuously like water","B1","stream",[["The river flows through the old town.","川は古い町並みを流れています。"],["Warm air flowed into the room through the window.","暖かい空気が窓から部屋に流れ込みました。"]],"町を流れる川","original-20261114-b1-08"],["VDO-261114-K-00013","flow","noun","流れ・流量","the movement of something in a steady stream","B1","movement",[["The team measured the flow of water in the canal.","チームは運河の水の流れを測定しました。"],["Clear signs improved the flow of visitors through the hall.","わかりやすい標識でホール内の人の流れがよくなりました。"]],"運河の水の流れ","original-20261114-b1-08"],["VDO-261114-K-00014","flu","noun","インフルエンザ","a viral illness that often causes fever and tiredness","B1","influenza",[["Several students missed school because of the flu.","数人の生徒がインフルエンザのため学校を休みました。"],["The clinic shared advice on preventing the flu.","診療所はインフルエンザの予防方法を紹介しました。"]],"診療所の予防案内","original-20261114-b1-08"],["VDO-261114-K-00015","fluent","adjective","流暢な","able to speak a language easily and smoothly","B1","proficient (related)",[["Her brother is fluent in Spanish.","彼女の兄はスペイン語が流暢です。"],["Regular speaking practice helped him become more fluent.","定期的なスピーキング練習が彼の流暢さの向上につながりました。"]],"多言語で会話する人","original-20261114-b1-08"],["VDO-261114-K-00016","fluently","adverb","流暢に","in a smooth and confident way when speaking","B1","smoothly",[["She spoke fluently during the interview.","彼女は面接で流暢に話しました。"],["He hopes to read Japanese aloud more fluently.","彼は日本語をもっと流暢に音読したいと考えています。"]],"面接で流暢に話す","original-20261114-b1-08"],["VDO-261114-K-00017","flunk","verb","試験に落ちる（口語）","to fail a test or course","B1","fail",[["He flunked the quiz because he had not studied.","彼は勉強していなかったので小テストに落ちました。"],["The character flunked math but later improved.","その登場人物は数学で落第しましたが、後に成績が上がりました。"]],"試験結果を見る生徒","original-20261114-b1-08"],["VDO-261114-K-00018","flute","noun","フルート","a musical instrument played by blowing across an opening","B1","wind instrument",[["She played the flute at the school concert.","彼女は学校の演奏会でフルートを演奏しました。"],["The flute melody began softly.","フルートの旋律は静かに始まりました。"]],"フルートの演奏","original-20261114-b1-08"],["VDO-261114-K-00019","fold","verb","折りたたむ・折る","to bend something so one part lies over another","B1","crease",[["Fold the paper in half before cutting it.","紙を切る前に半分に折ってください。"],["She folded the map and put it in her bag.","彼女は地図を折りたたんでかばんに入れました。"]],"地図を折りたたむ","original-20261114-b1-08"],["VDO-261114-K-00020","fold","noun","折り目・折りたたみ部分","a line or part made by bending material","B1","crease",[["The letter had a fold across the center.","その手紙には中央に折り目がありました。"],["She pressed the fold flat with her hand.","彼女は手で折り目を平らに押さえました。"]],"紙の折り目","original-20261114-b1-08"],["VDO-261114-K-00021","folk","adjective","民間の・伝統的な","connected with traditional music or customs of ordinary people","B1","traditional",[["The students learned a Japanese folk dance.","生徒たちは日本の民俗舞踊を習いました。"],["A folk song opened the cultural festival.","民謡で文化祭が始まりました。"]],"民俗舞踊を踊る生徒","original-20261114-b1-08"],["VDO-261114-K-00022","fond","adjective","好きで・親しみを持つ","having affection or liking for someone or something","B1","affectionate (related)",[["My grandfather is fond of old trains.","祖父は古い列車が好きです。"],["She grew fond of her host family's cooking.","彼女はホームステイ先の家庭料理が好きになりました。"]],"列車を見る祖父","original-20261114-b1-08"],["VDO-261114-K-00023","fondness","noun","愛着・好意","a feeling of warm liking","B1","affection",[["He spoke with fondness about his childhood town.","彼は子どもの頃の町について愛着を込めて話しました。"],["Her fondness for animals led her to volunteer at a shelter.","動物への愛情がきっかけで彼女は保護施設でボランティアを始めました。"]],"保護犬に接する人","original-20261114-b1-08"],["VDO-261114-K-00024","foolish","adjective","愚かな・考えが浅い","showing poor judgment","B1","unwise",[["It was foolish to leave the tent open in the rain.","雨の中でテントを開けたままにしたのは愚かでした。"],["He realized his foolish mistake and apologized.","彼は自分の愚かな間違いに気づいて謝りました。"]],"雨に濡れたテント","original-20261114-b1-08"],["VDO-261114-K-00025","foot","noun","足・足首より下","the part of the body used for standing and walking","B1",null,[["She injured her foot during the hike.","彼女はハイキング中に足をけがしました。"],["The child took off one shoe and checked his foot.","その子は片方の靴を脱いで足を確認しました。"]],"ハイキングの靴","original-20261114-b1-08"],["VDO-261114-K-00026","foot","noun","フィート（長さの単位）","a unit of length equal to twelve inches","B1","12 inches",[["The sign says the water is six feet deep.","看板には水深が6フィートと書かれています。"],["The shelf is about four feet wide.","その棚の幅は約4フィートです。"]],"フィート表示の標識","original-20261114-b1-08"],["VDO-261114-K-00027","forbidden","adjective","禁止された","not allowed by a rule or law","B1","prohibited",[["Swimming is forbidden near the dam.","ダムの近くでは水泳が禁止されています。"],["The signs show that photography is forbidden in this room.","標識にはこの部屋での撮影は禁止と示されています。"]],"撮影禁止の標識","original-20261114-b1-08"],["VDO-261114-K-00028","forehead","noun","額・ひたい","the part of the face above the eyes","B1","brow (area)",[["The child wiped sweat from his forehead.","その子は額の汗を拭きました。"],["She touched her forehead to check for a fever.","彼女は熱があるか確かめるため額に触れました。"]],"額の汗を拭く","original-20261114-b1-08"],["VDO-261114-K-00029","formal","adjective","正式な・改まった","suitable for official or serious occasions","B1","official",[["The invitation used formal English.","招待状には改まった英語が使われていました。"],["Students wore formal clothes for the ceremony.","生徒たちは式典に正装で参加しました。"]],"正式な招待状","original-20261114-b1-08"],["VDO-261114-K-00030","formally","adverb","正式に・公式に","in an official or proper way","B1","officially",[["The principal formally welcomed the visitors.","校長は訪問者を正式に歓迎しました。"],["The school formally approved the exchange plan.","学校は交流計画を正式に承認しました。"]],"訪問者を迎える式典","original-20261114-b1-08"],["VDO-261114-K-00031","format","noun","形式・書式","the way information or a document is arranged","B1","layout",[["The teacher showed us the correct essay format.","先生は作文の正しい書式を示してくれました。"],["Choose a video format that works on tablets.","タブレットで動く動画形式を選んでください。"]],"作文の書式見本","original-20261114-b1-08"],["VDO-261114-K-00032","format","verb","書式を整える","to arrange text or data in a particular structure","B1","lay out",[["She formatted the report with clear headings.","彼女は明確な見出しを使って報告書の書式を整えました。"],["The program formats the questions automatically.","そのプログラムは問題の書式を自動で整えます。"]],"文書レイアウト編集","original-20261114-b1-08"],["VDO-261114-K-00033","former","adjective","以前の・元の","having held a position or role in the past","B1","previous",[["A former student returned to give a talk.","卒業生が講演のために戻ってきました。"],["The building was a former train station.","その建物は以前は駅でした。"]],"昔の駅舎","original-20261114-b1-08"],["VDO-261114-K-00034","formula","noun","公式・計算式","a rule expressed using numbers or symbols","B1","equation (related)",[["Use the formula to calculate the area.","面積を計算するために公式を使ってください。"],["The class learned a formula for measuring speed.","クラスは速さを求める公式を学びました。"]],"面積の公式","original-20261114-b1-08"],["VDO-261114-K-00035","formula","noun","調合方法・決まったやり方","a fixed method for doing or making something","B1","method",[["The team developed a formula for mixing the paint.","チームは絵の具を混ぜる決まった方法を考えました。"],["There is no simple formula for becoming a good teacher.","よい教師になるための単純な決まりきった方法はありません。"]],"塗料の調合表","original-20261114-b1-08"],["VDO-261114-K-00036","forth","adverb","前へ・先へ","forward in place or time","B1","forward",[["The captain called the players forth for the ceremony.","キャプテンは式典のため選手たちを前に呼び出しました。"],["The river rushed forth after the gate opened.","水門が開くと川の水は勢いよく前へ流れ出しました。"]],"水門を流れ出る水","original-20261114-b1-08"],["VDO-261114-K-00037","fortnight","noun","2週間","a period of fourteen days","B1","two weeks",[["The exchange project lasted a fortnight.","交流プロジェクトは2週間続きました。"],["We will review the plan in a fortnight.","2週間後にその計画を見直します。"]],"二週間の予定表","original-20261114-b1-08"],["VDO-261114-K-00038","fortunate","adjective","幸運な","having good luck or favorable circumstances","B1","lucky",[["We were fortunate to find shelter before the storm.","嵐の前に避難場所を見つけられて幸運でした。"],["She felt fortunate to study with students from many countries.","彼女は多くの国の生徒と学べることを幸運に思いました。"]],"嵐前に避難できた人","original-20261114-b1-08"],["VDO-261114-K-00039","fountain","noun","噴水","a structure that sends water into the air","B1","water feature",[["Children played beside the fountain in the square.","子どもたちは広場の噴水のそばで遊びました。"],["The city restored the old stone fountain.","市は古い石の噴水を修復しました。"]],"広場の噴水","original-20261114-b1-08"],["VDO-261114-K-00040","fragment","noun","破片・断片","a small piece of something larger","B1","piece",[["The archaeologist found a fragment of pottery.","考古学者は陶器の破片を見つけました。"],["Only a fragment of the old letter remained.","古い手紙は一部の断片だけが残っていました。"]],"陶器の破片","original-20261114-b1-08"],["VDO-261114-K-00041","freely","adverb","自由に・遠慮なく","without restrictions or fear","B1","without restriction",[["Students could freely choose their project topics.","生徒たちは研究テーマを自由に選べました。"],["The children moved freely around the garden.","子どもたちは庭を自由に動き回りました。"]],"自由にテーマを選ぶ","original-20261114-b1-08"],["VDO-261114-K-00042","freezer","noun","冷凍庫","a machine or compartment for keeping things frozen","B1","freezing compartment",[["Put the ice cream in the freezer.","アイスクリームを冷凍庫に入れてください。"],["The school kitchen has a large freezer.","学校の厨房には大きな冷凍庫があります。"]],"冷凍庫の食品","original-20261114-b1-08"],["VDO-261114-K-00043","freezing","adjective","凍るように寒い","extremely cold","B1","icy",[["It was freezing on the mountain before sunrise.","日の出前の山は凍えるほど寒かったです。"],["The students waited outside in freezing weather.","生徒たちは凍えるような寒さの中で外で待ちました。"]],"冬山の寒さ","original-20261114-b1-08"],["VDO-261114-K-00044","freezing","noun","凍結","the process of becoming solid because of cold","B1","solidification",[["Freezing turns liquid water into ice.","凍結によって液体の水は氷になります。"],["The experiment compared freezing and melting.","実験では凍結と融解を比較しました。"]],"水と氷の変化","original-20261114-b1-08"],["VDO-261114-K-00045","frequency","noun","頻度・回数","how often something happens within a period","B1","rate",[["The survey measured the frequency of daily reading.","その調査は毎日の読書の頻度を測りました。"],["The teacher checked the frequency of students' practice.","教師は生徒たちの練習頻度を確認しました。"]],"読書頻度の棒グラフ","original-20261114-b1-08"],["VDO-261114-K-00046","frequent","adjective","頻繁な・たびたびの","happening many times or regularly","B1","common",[["Frequent short breaks can help students concentrate.","短い休憩を頻繁に取ることは集中の助けになり得ます。"],["The village experiences frequent heavy rain in summer.","その村では夏に大雨が頻繁に降ります。"]],"休憩の時間割","original-20261114-b1-08"],["VDO-261114-K-00047","frequently","adverb","頻繁に・よく","many times or often","B1","often",[["She frequently uses picture cards in class.","彼女は授業で絵カードを頻繁に使います。"],["The bus frequently arrives late during the rainy season.","そのバスは雨季に頻繁に遅れて到着します。"]],"授業で使う絵カード","original-20261114-b1-08"],["VDO-261114-L-00001","freshman","noun","大学・高校などの1年生（米）","a student in the first year of a school or college","B1","first-year student",[["My cousin is a freshman at a university in Tokyo.","いとこは東京の大学の1年生です。"],["The freshmen attended an orientation on Monday.","新入生たちは月曜日にオリエンテーションに参加しました。"]],"大学の新入生","original-20261114-b1-09"],["VDO-261114-L-00002","friendliness","noun","親しみやすさ・友好的な態度","the quality of being kind and welcoming","B1","warmth",[["The visitors appreciated the friendliness of the host families.","訪問者たちは受け入れ家庭の親しみやすさに感謝しました。"],["Her friendliness helped new classmates feel comfortable.","彼女の親しみやすさのおかげで新しいクラスメートたちは安心できました。"]],"歓迎するホスト家庭","original-20261114-b1-09"],["VDO-261114-L-00003","fright","noun","恐怖・驚き","a sudden strong feeling of fear","B1","scare",[["The loud sound gave the child a fright.","大きな音にその子どもはびっくりしました。"],["She recovered from her fright when she saw the dog was safe.","犬が無事だとわかって彼女は恐怖から立ち直りました。"]],"突然の大きな音","original-20261114-b1-09"],["VDO-261114-L-00004","frost","noun","霜","a thin white layer of ice forming on cold surfaces","B1","ice crystals",[["Frost covered the grass early in the morning.","早朝、芝生は霜で覆われていました。"],["The farmers protected young plants from frost.","農家の人たちは若い植物を霜から守りました。"]],"霜のついた芝生","original-20261114-b1-09"],["VDO-261114-L-00005","frozen","adjective","凍った・冷凍の","made solid or very cold by freezing","B1","icy",[["The lake was frozen after several cold nights.","寒い夜が何日か続き湖は凍っていました。"],["She cooked frozen vegetables for dinner.","彼女は夕食に冷凍野菜を調理しました。"]],"凍った湖","original-20261114-b1-09"],["VDO-261114-L-00006","frustrated","adjective","いらいらした・思うようにいかず落胆した","upset because something is difficult or not going well","B1","discouraged",[["He felt frustrated when the microphone stopped working.","マイクが動かなくなって彼はいらいらしました。"],["She was frustrated by her slow progress in pronunciation.","発音の上達が遅くて彼女はもどかしく感じました。"]],"うまくいかない発音練習","original-20261114-b1-09"],["VDO-261114-L-00007","frustration","noun","いらだち・もどかしさ","a feeling of being upset when progress is blocked","B1","annoyance",[["The long delay caused frustration among passengers.","長い遅延で乗客たちはいらだちを感じました。"],["The teacher understood the students' frustration with the new app.","教師は新しいアプリに対する生徒たちのもどかしさを理解しました。"]],"アプリの操作に苦労する","original-20261114-b1-09"],["VDO-261114-L-00008","frying pan","noun","フライパン","a flat pan used for cooking food over heat","B1","skillet",[["Heat the frying pan before adding the vegetables.","野菜を入れる前にフライパンを温めてください。"],["The cook placed the frying pan on the stove.","料理人はフライパンをコンロに置きました。"]],"コンロのフライパン","original-20261114-b1-09"],["VDO-261114-L-00009","fuel","noun","燃料","a material used to produce heat or power","B1","energy source",[["The bus uses less fuel than the older model.","そのバスは旧型より燃料の使用量が少ないです。"],["Scientists compared several types of clean fuel.","科学者たちはいくつかのクリーン燃料を比較しました。"]],"バスの燃料補給","original-20261114-b1-09"],["VDO-261114-L-00010","fuel","verb","燃料を供給する・促進する","to supply energy or make an activity stronger","B1","power",[["Solar energy fuels some of the school's equipment.","太陽エネルギーは学校の設備の一部に電力を供給します。"],["The successful event fueled interest in international exchange.","行事の成功は国際交流への関心を高めました。"]],"太陽光で動く設備","original-20261114-b1-09"],["VDO-261114-L-00011","full stop","noun","ピリオド・文の終止符（英）","the punctuation mark placed at the end of a statement","B1","period (US)",[["Put a full stop at the end of the sentence.","文末にピリオドを付けてください。"],["The student forgot the full stop after the last word.","生徒は最後の単語のあとにピリオドを付け忘れました。"]],"英文末のピリオド","original-20261114-b1-09"],["VDO-261114-L-00012","full-time","adjective","常勤の・フルタイムの","working for the usual number of hours each week","B1","not part-time",[["She accepted a full-time teaching position.","彼女は常勤の教師の職を引き受けました。"],["The hospital is looking for full-time nurses.","病院は常勤の看護師を募集しています。"]],"常勤職員の求人","original-20261114-b1-09"],["VDO-261114-L-00013","fund","noun","基金・資金","money set aside for a particular purpose","B1","reserve",[["The club created a fund for travel expenses.","部活動は交通費のための資金を設けました。"],["Donations increased the scholarship fund.","寄付によって奨学基金が増えました。"]],"奨学金用の募金箱","original-20261114-b1-09"],["VDO-261114-L-00014","fund","verb","資金を提供する","to provide money for a project","B1","finance",[["The town funded a new children's library.","町は新しい児童図書館に資金を提供しました。"],["A grant funded the school's science project.","助成金が学校の科学プロジェクトを支えました。"]],"科学プロジェクトの助成","original-20261114-b1-09"],["VDO-261114-L-00015","funeral","noun","葬儀","a ceremony held after someone dies","B1","memorial service (related)",[["The family held a small funeral for their grandfather.","家族は祖父のために小さな葬儀を行いました。"],["He took a day off to attend a funeral.","彼は葬儀に参列するため1日休みました。"]],"葬儀に飾られた花","original-20261114-b1-09"],["VDO-261114-L-00016","fur","noun","動物の毛・毛皮","thick soft hair covering an animal's body","B1","animal hair",[["The rabbit has soft white fur.","そのウサギは柔らかい白い毛に覆われています。"],["The cat's fur became wet in the rain.","猫の毛は雨で濡れました。"]],"白い毛のウサギ","original-20261114-b1-09"],["VDO-261114-L-00017","furnish","verb","家具を備え付ける","to put furniture and equipment into a room","B1","equip",[["The school furnished the new classroom with round tables.","学校は新しい教室に丸いテーブルを備え付けました。"],["They furnished the apartment using secondhand furniture.","彼らは中古家具を使ってアパートに家具をそろえました。"]],"丸い机の新しい教室","original-20261114-b1-09"],["VDO-261114-L-00018","furthermore","adverb","さらに・そのうえ","used to add an important point to what was said","B1","moreover",[["The plan saves time; furthermore, it reduces paper waste.","その計画は時間を節約し、さらに紙のごみも減らします。"],["The park is safe; furthermore, it is easy to reach by bus.","その公園は安全で、そのうえバスで簡単に行けます。"]],"利点を示すプレゼン","original-20261114-b1-09"],["VDO-261114-L-00019","furthest","adjective","最も遠い","at the greatest distance from a place","B1","farthest",[["The furthest classroom is at the end of the corridor.","最も遠い教室は廊下の突き当たりにあります。"],["Our team traveled to the furthest village on the map.","私たちのチームは地図上で最も遠い村へ行きました。"]],"廊下の端の教室","original-20261114-b1-09"],["VDO-261114-L-00020","fuss","noun","大騒ぎ・過剰な心配","unnecessary excitement or concern about something small","B1","commotion",[["There was a fuss over the missing name tag.","なくなった名札をめぐって大騒ぎになりました。"],["The coach asked us not to make a fuss about the mistake.","コーチはそのミスを大げさに騒がないよう求めました。"]],"なくした名札を探す","original-20261114-b1-09"],["VDO-261114-L-00021","gallon","noun","ガロン（液体量の単位）","a unit for measuring liquids used in some countries","B1","liquid measure",[["The container holds one US gallon of water.","その容器には米国の1ガロン分の水が入ります。"],["The recipe listed the milk in gallons rather than liters.","そのレシピでは牛乳の量がリットルではなくガロンで示されていました。"]],"液体の容器と量","original-20261114-b1-09"],["VDO-261114-L-00022","gap","noun","すき間・空間","an empty space between two things","B1","opening",[["A narrow gap separated the two buildings.","2つの建物の間には狭いすき間がありました。"],["Please leave a small gap between the chairs.","椅子の間に少しすき間を空けてください。"]],"椅子の間のすき間","original-20261114-b1-09"],["VDO-261114-L-00023","gap","noun","格差・差","an important difference between groups or levels","B1","difference",[["The project aims to close the learning gap.","その計画は学習格差を縮めることを目指しています。"],["The survey found a gap between rural and urban services.","調査では農村部と都市部のサービスに差があることがわかりました。"]],"都市と農村の比較","original-20261114-b1-09"],["VDO-261114-L-00024","gardening","noun","園芸・庭仕事","the activity of growing and caring for plants","B1","plant growing",[["Gardening helped the students learn about seasons.","園芸は生徒たちが季節について学ぶ助けになりました。"],["My aunt enjoys gardening on weekends.","おばは週末に庭仕事を楽しみます。"]],"学校の花壇作り","original-20261114-b1-09"],["VDO-261114-L-00025","garment","noun","衣服・衣類の一着","one item of clothing","B1","piece of clothing",[["The garment was made from recycled cotton.","その衣服は再生綿から作られました。"],["Each garment was labeled with its size.","衣服には一着ずつサイズが表示されていました。"]],"再生素材の衣服","original-20261114-b1-09"],["VDO-261114-L-00026","gay","adjective","同性愛の・ゲイの","attracted romantically to people of the same sex","B1","homosexual",[["The book includes a gay character who supports his friends.","その本には友人たちを支えるゲイの登場人物が出てきます。"],["The discussion focused on equal rights for gay people.","その話し合いは同性愛者の平等な権利に焦点を当てました。"]],"多様性を尊重する教室","original-20261114-b1-09"],["VDO-261114-L-00027","gee","interjection","わあ・へえ（口語の驚き）","an informal expression of surprise","B1","wow",[["Gee, I didn't expect the robot to move that quickly!","わあ、ロボットがあんなに速く動くとは思わなかった。"],["Gee, that was a difficult puzzle!","わあ、難しいパズルだったね。"]],"ロボットに驚く生徒","original-20261114-b1-09"],["VDO-261114-L-00028","gene","noun","遺伝子","a unit of information in cells that influences inherited traits","B1","unit of heredity",[["Scientists identified a gene related to the plant's color.","科学者たちは植物の色に関係する遺伝子を特定しました。"],["The lesson explained how a gene can affect a trait.","授業では遺伝子が特徴に影響する仕組みを説明しました。"]],"DNAと遺伝子の図","original-20261114-b1-09"],["VDO-261114-L-00029","general","adjective","一般的な・全体的な","not limited to one specific case","B1","overall",[["The guide gave a general introduction to the museum.","案内人は博物館の全体的な紹介をしました。"],["We discussed the general causes of water pollution.","私たちは水質汚染の一般的な原因を話し合いました。"]],"博物館の全体案内","original-20261114-b1-09"],["VDO-261114-L-00030","general","noun","将軍・軍の高級司令官","a high-ranking officer in an army","B1","army commander",[["The history book describes a general who led the army.","歴史の本には軍を率いた将軍について書かれています。"],["The general's portrait hangs in the museum.","その将軍の肖像画は博物館に飾られています。"]],"歴史博物館の将軍像","original-20261114-b1-09"],["VDO-261114-L-00031","generally","adverb","一般に・ふつう","in most situations or as a general rule","B1","usually",[["People generally need enough sleep to concentrate.","人は一般に集中するため十分な睡眠が必要です。"],["The buses are generally on time in this town.","この町のバスはふつう時間どおりです。"]],"規則正しい睡眠","original-20261114-b1-09"],["VDO-261114-L-00032","generous","adjective","気前がよい・寛大な","willing to give time, money, or help to others","B1","giving",[["A generous neighbor donated books to the school.","気前のよい近所の人が学校に本を寄付しました。"],["She was generous with her time when helping beginners.","彼女は初心者を助けるため惜しみなく時間を使いました。"]],"学校への本の寄付","original-20261114-b1-09"],["VDO-261114-M-00001","genetic","adjective","遺伝の・遺伝子に関する","connected with genes or inherited traits","B1","hereditary",[["The researchers studied genetic differences between the plants.","研究者たちは植物間の遺伝的な違いを調べました。"],["Some medical conditions have a genetic cause.","一部の病気には遺伝的な原因があります。"]],"植物の遺伝的特徴","original-20261114-b1-10"],["VDO-261114-M-00002","genetically","adverb","遺伝的に・遺伝子の面で","in a way connected with genes","B1","by heredity",[["The two varieties are genetically different.","その2つの品種は遺伝的に異なります。"],["The researchers examined how traits are genetically passed on.","研究者たちは特徴がどのように遺伝的に受け継がれるか調べました。"]],"二品種のDNA比較","original-20261114-b1-10"],["VDO-261114-M-00003","genetics","noun","遺伝学","the scientific study of genes and inheritance","B1","study of heredity",[["She is studying genetics at university.","彼女は大学で遺伝学を学んでいます。"],["Genetics helps explain why children resemble their parents.","遺伝学は子どもが親に似る理由の説明に役立ちます。"]],"遺伝子を学ぶ学生","original-20261114-b1-10"],["VDO-261114-M-00004","gentleman","noun","紳士・礼儀正しい男性","a polite or respectful man","B1","polite man",[["An elderly gentleman offered his seat to a child.","年配の紳士が子どもに席を譲りました。"],["The guide introduced the gentleman waiting at the entrance.","案内人は入口で待っている男性を紹介しました。"]],"席を譲る男性","original-20261114-b1-10"],["VDO-261114-M-00005","geographical","adjective","地理的な・地理に関する","connected with the location and physical features of places","B1","geographic",[["The students compared the geographical features of two islands.","生徒たちは2つの島の地理的特徴を比較しました。"],["Geographical distance can make school exchanges difficult.","地理的な距離によって学校間交流が難しくなることがあります。"]],"二つの島の地図","original-20261114-b1-10"],["VDO-261114-M-00006","geography","noun","地理・地理学","the study of the earth's places and environments","B1","study of places",[["In geography class, we mapped the major rivers.","地理の授業で私たちは主要な川を地図に記しました。"],["She enjoys studying the geography of Southeast Asia.","彼女は東南アジアの地理を学ぶのが好きです。"]],"東南アジアの地図","original-20261114-b1-10"],["VDO-261114-M-00007","geology","noun","地質学","the study of rocks and the earth's structure","B1","earth science",[["Geology helps explain how mountains form.","地質学は山ができる仕組みを説明する助けになります。"],["The students collected rock samples for their geology project.","生徒たちは地質学の研究用に岩石標本を集めました。"]],"岩石標本を調べる","original-20261114-b1-10"],["VDO-261114-M-00008","gesture","noun","身ぶり・しぐさ","a movement of the hands or body expressing meaning","B1","body movement",[["He used a gesture to invite the guests inside.","彼は身ぶりで来客を中へ招きました。"],["The same gesture can mean different things in different cultures.","同じ身ぶりでも文化によって意味が異なることがあります。"]],"文化ごとの身ぶり","original-20261114-b1-10"],["VDO-261114-M-00009","gesture","verb","身ぶりで示す","to communicate using movements rather than words","B1","signal",[["The guide gestured toward the exit.","案内人は出口の方を身ぶりで示しました。"],["She gestured for the class to move closer.","彼女はクラスにもっと近づくよう身ぶりで伝えました。"]],"出口を指し示す案内人","original-20261114-b1-10"],["VDO-261114-M-00010","giant","adjective","巨大な","much larger than usual","B1","enormous",[["A giant tree stood beside the old school.","古い学校のそばには巨大な木が立っていました。"],["The museum displayed a giant model of the solar system.","博物館は太陽系の巨大な模型を展示していました。"]],"巨大な太陽系模型","original-20261114-b1-10"],["VDO-261114-M-00011","giant","noun","巨人・巨大なもの","an unusually large person or thing","B1","huge figure",[["A friendly giant appeared in the children's story.","子ども向けの物語に親切な巨人が登場しました。"],["The statue showed a giant holding a mountain.","その像には山を持ち上げる巨人が描かれていました。"]],"物語の巨人","original-20261114-b1-10"],["VDO-261114-M-00012","gifted","adjective","才能に恵まれた","having unusual natural ability in an area","B1","talented",[["The gifted violinist performed at the festival.","才能あるバイオリン奏者が祭りで演奏しました。"],["The school offers extra challenges for gifted learners.","その学校は才能のある学習者に追加の課題を用意しています。"]],"バイオリン演奏","original-20261114-b1-10"],["VDO-261114-M-00013","giggle","verb","くすくす笑う","to laugh quietly in a light or nervous way","B1","chuckle",[["The children giggled at the funny drawing.","子どもたちはおかしな絵を見てくすくす笑いました。"],["She giggled when her friend made a silly face.","友達が変な顔をしたので彼女はくすくす笑いました。"]],"おかしな絵を見て笑う","original-20261114-b1-10"],["VDO-261114-M-00014","ginger","noun","ショウガ","a spicy root used to flavor food and drinks","B1","spice root",[["She added fresh ginger to the soup.","彼女はスープに新鮮なショウガを加えました。"],["The cafe serves hot tea with ginger.","そのカフェではショウガ入りの温かい紅茶を出します。"]],"しょうがと紅茶","original-20261114-b1-10"],["VDO-261114-M-00015","giraffe","noun","キリン","a tall African animal with a very long neck","B1",null,[["The giraffe reached the leaves at the top of the tree.","キリンは木の上の葉に届きました。"],["We learned how giraffes use their long necks.","私たちはキリンが長い首をどう使うか学びました。"]],"木の葉を食べるキリン","original-20261114-b1-10"],["VDO-261114-M-00016","glance","verb","ちらっと見る","to look quickly at something","B1","look briefly",[["She glanced at the clock before speaking.","彼女は話し始める前に時計をちらっと見ました。"],["He glanced at his notes during the presentation.","彼は発表中にメモをちらっと見ました。"]],"時計をちらりと見る","original-20261114-b1-10"],["VDO-261114-M-00017","glance","noun","ちらっと見ること","a quick look","B1","brief look",[["At first glance, the two images looked identical.","一見すると2枚の画像は同じに見えました。"],["He took a glance at the map and chose a road.","彼は地図をちらっと見て道を選びました。"]],"二枚の絵を見比べる","original-20261114-b1-10"],["VDO-261114-M-00018","glide","verb","滑るように進む","to move smoothly and quietly","B1","slide smoothly",[["The swan glided across the lake.","白鳥は湖を滑るように進みました。"],["The paper plane glided toward the window.","紙飛行機は窓の方へ滑らかに飛びました。"]],"湖を進む白鳥","original-20261114-b1-10"],["VDO-261114-M-00019","glimpse","noun","ちらりと見えること","a brief or incomplete view of something","B1","quick view",[["We caught a glimpse of the mountain through the clouds.","私たちは雲の間から山をちらりと見ました。"],["The documentary offers a glimpse of life in the village.","そのドキュメンタリーは村の暮らしを垣間見せます。"]],"雲間の山","original-20261114-b1-10"],["VDO-261114-M-00020","glimpse","verb","ちらりと見る","to see something briefly","B1","see briefly",[["She glimpsed a deer between the trees.","彼女は木々の間にシカをちらりと見ました。"],["We glimpsed the sea as the train passed the hill.","電車が丘を通るとき海がちらりと見えました。"]],"木々の間のシカ","original-20261114-b1-10"],["VDO-261114-M-00021","glint","noun","きらりと光ること","a brief small flash of reflected light","B1","sparkle",[["A glint of sunlight appeared on the water.","水面に日光がきらりと光りました。"],["She noticed a glint of metal in the sand.","彼女は砂の中で金属がきらっと光るのに気づきました。"]],"水面の小さなきらめき","original-20261114-b1-10"],["VDO-261114-M-00022","glorious","adjective","輝かしい・見事な","extremely beautiful or worthy of admiration","B1","splendid",[["We enjoyed a glorious sunrise over the sea.","私たちは海に昇る見事な日の出を楽しみました。"],["The team celebrated a glorious victory in the final.","チームは決勝での輝かしい勝利を祝いました。"]],"海から昇る日の出","original-20261114-b1-10"],["VDO-261114-M-00023","glory","noun","栄光・名誉","high praise or honor for an achievement","B1","honor",[["The town remembered the glory of its old trading port.","町はかつての貿易港の栄光をしのびました。"],["The players shared the glory of the championship.","選手たちは優勝の栄光を分かち合いました。"]],"優勝トロフィー","original-20261114-b1-10"],["VDO-261114-M-00024","goalkeeper","noun","ゴールキーパー","a player who protects the goal in sports such as football","B1","goalie",[["The goalkeeper saved a difficult penalty kick.","ゴールキーパーは難しいPKを止めました。"],["Our goalkeeper practiced catching high balls.","私たちのゴールキーパーは高いボールを捕る練習をしました。"]],"PKを防ぐゴールキーパー","original-20261114-b1-10"],["VDO-261114-M-00025","goddess","noun","女神","a female god in a religion or story","B1","female deity",[["The sculpture represents an ancient goddess.","その彫刻は古代の女神を表しています。"],["The students read a myth about a sea goddess.","生徒たちは海の女神の神話を読みました。"]],"古代の女神の彫刻","original-20261114-b1-10"],["VDO-261114-M-00026","golfer","noun","ゴルフをする人","a person who plays golf","B1","golf player",[["The golfer practiced putting on the green.","ゴルファーはグリーンでパッティングを練習しました。"],["A young golfer won the regional tournament.","若いゴルファーが地域大会で優勝しました。"]],"グリーンのゴルファー","original-20261114-b1-10"],["VDO-261114-M-00027","goodness","noun","善良さ・親切さ","the quality of being kind and morally good","B1","kindness",[["Her goodness showed in the way she treated others.","彼女の善良さは人への接し方に表れていました。"],["The story celebrates the goodness of ordinary people.","その物語は普通の人々の善良さをたたえています。"]],"人助けをする人","original-20261114-b1-10"],["VDO-261114-M-00028","goods","noun","商品・物資","things that are produced or sold","B1","products",[["The truck delivered goods to the mountain village.","トラックは山間の村に物資を届けました。"],["The store sells locally made goods.","その店は地元で作られた商品を売っています。"]],"地元の商品","original-20261114-b1-10"],["VDO-261114-M-00029","gorgeous","adjective","とても美しい・豪華な","extremely beautiful or attractive","B1","beautiful",[["The garden looked gorgeous in spring.","その庭は春にとても美しく見えました。"],["She wore a gorgeous handmade dress.","彼女はとても美しい手作りのドレスを着ていました。"]],"春の美しい庭","original-20261114-b1-10"],["VDO-261114-M-00030","gorilla","noun","ゴリラ","a large African ape with strong arms","B1","great ape",[["The gorilla sat quietly beside a tree.","ゴリラは木のそばで静かに座っていました。"],["Researchers observed how gorillas care for their young.","研究者たちはゴリラが子どもの世話をする様子を観察しました。"]],"子を世話するゴリラ","original-20261114-b1-10"],["VDO-261114-M-00031","gossip","noun","うわさ話・ゴシップ","informal talk about other people's private lives","B1","rumor",[["The teacher asked students not to spread harmful gossip.","先生は傷つけるようなうわさ話を広めないよう生徒に求めました。"],["The magazine printed gossip about famous actors.","その雑誌は有名な俳優たちのうわさ話を載せました。"]],"うわさを広めない掲示","original-20261114-b1-10"],["VDO-261114-M-00032","gossip","verb","うわさ話をする","to talk about other people's private affairs","B1","spread rumors",[["They gossiped about the new television program.","彼らは新しいテレビ番組の出演者についてうわさ話をしました。"],["She refused to gossip about her classmates.","彼女はクラスメートについてうわさ話をするのを拒みました。"]],"友人同士の内緒話","original-20261114-b1-10"],["VDO-261114-M-00033","governor","noun","州知事・地域の長","a person who officially leads a state or region","B1","regional leader",[["The governor announced a plan to repair local roads.","州知事は地元の道路を修理する計画を発表しました。"],["Students interviewed a former governor about public service.","生徒たちは元知事に公共サービスについてインタビューしました。"]],"道路整備の発表","original-20261114-b1-10"],["VDO-261114-M-00034","gown","noun","長い礼服・ガウン","a long formal dress or special robe","B1","formal dress",[["She wore a blue gown to the ceremony.","彼女は式典に青いガウンを着ていきました。"],["The graduates wore gowns during the ceremony.","卒業生たちは式典でガウンを着ていました。"]],"卒業式のガウン","original-20261114-b1-10"],["VDO-261114-M-00035","grab","verb","素早くつかむ","to take hold of something quickly","B1","seize",[["He grabbed the railing when he slipped.","彼は足を滑らせたとき手すりをつかみました。"],["She grabbed her bag and hurried to the bus.","彼女はかばんをさっとつかんでバスに急ぎました。"]],"手すりをつかむ手","original-20261114-b1-10"],["VDO-261114-M-00036","graceful","adjective","優雅な・しなやかな","moving or looking smooth and beautiful","B1","elegant",[["The dancer made a graceful turn.","踊り手は優雅に回転しました。"],["A graceful bird landed on the water.","優雅な鳥が水面に降り立ちました。"]],"優雅なダンサー","original-20261114-b1-10"],["VDO-261114-M-00037","graduation","noun","卒業・卒業式","the act of finishing a course of study","B1","completion of school",[["The students prepared speeches for graduation.","生徒たちは卒業式のスピーチを準備しました。"],["Her parents traveled to attend her graduation.","両親は彼女の卒業式に出席するため旅行しました。"]],"卒業式の演壇","original-20261114-b1-10"],["VDO-261114-M-00038","grant","noun","助成金・補助金","money given to support a project or study","B1","funding award",[["The school received a grant for science equipment.","学校は科学機器のための助成金を受け取りました。"],["She used a research grant to study local rivers.","彼女は地域の川を研究するために研究助成金を使いました。"]],"研究助成金の通知","original-20261114-b1-10"],["VDO-261114-M-00039","grant","verb","正式に与える・認める","to officially give a right, request, or permission","B1","allow",[["The principal granted permission for the event.","校長はその行事を行う許可を与えました。"],["The university granted her an extension on the report.","大学は彼女のレポートの提出期限延長を認めました。"]],"行事の許可書","original-20261114-b1-10"],["VDO-261114-M-00040","graph","noun","グラフ","a drawing showing how numbers or amounts are related","B1","chart",[["The graph shows an increase in reading speed.","グラフは読書速度の向上を示しています。"],["We compared the two countries using a bar graph.","私たちは棒グラフを使って2か国を比較しました。"]],"読書速度の棒グラフ","original-20261114-b1-10"],["VDO-261114-M-00041","graphic","adjective","図や画像による・視覚的な","using pictures or visual designs","B1","visual",[["The worksheet includes a graphic explanation of the cycle.","ワークシートには循環の視覚的な説明が含まれています。"],["She designed a graphic poster for the festival.","彼女は祭り用に図を使ったポスターをデザインしました。"]],"図解ポスター","original-20261114-b1-10"],["VDO-261114-M-00042","graphics","noun","図形・コンピューター画像","pictures and visual elements used in media or software","B1","visuals",[["The students added graphics to their videos.","生徒たちは動画にグラフィックを追加しました。"],["Clear graphics made the instructions easier to follow.","わかりやすい図のおかげで指示に従いやすくなりました。"]],"動画のグラフィック","original-20261114-b1-10"],["VDO-261114-M-00043","gratitude","noun","感謝の気持ち","a feeling of being thankful","B1","thankfulness",[["The students expressed gratitude to their host families.","生徒たちはホストファミリーに感謝を伝えました。"],["She wrote a note of gratitude to the volunteers.","彼女はボランティアに感謝の手紙を書きました。"]],"ホスト家庭への感謝状","original-20261114-b1-10"]]};
